-- PUBLICATION-01: publication copy is generated by its own typed action, separately from
-- Opracuj. Additive only: every existing row and every action older code can write stays
-- valid, so the previous release runs unchanged against this schema.
alter table app.ai_runs drop constraint if exists ai_runs_action_check;
alter table app.ai_runs add constraint ai_runs_action_check check (action in (
  'develop', 'generate_hooks', 'fact_check', 'language_check', 'find_programme', 'generate_publication'
));
